import datetime
class Shift:
    def __init__(self, d):
        self.d = d
    def plus(self, n):
        self.d = self.d + datetime.timedelta(days=n)
        return self.d
s = Shift(datetime.date(2024, 1, 30))
print(s.plus(1))

